"use strict";
import { ProtocolVersion } from "@uniswap/client-pools/dist/pools/v1/types_pb";
import { CurrencyAmount } from "@uniswap/sdk-core";
import { TokenInfo } from "components/Liquidity/TokenInfo";
import { getLPBaseAnalyticsProperties } from "components/Liquidity/analytics";
import { useGetPoolTokenPercentage, usePositionCurrentPrice, usePositionDerivedInfo } from "components/Liquidity/hooks";
import { useRemoveLiquidityModalContext } from "components/RemoveLiquidity/RemoveLiquidityModalContext";
import { useRemoveLiquidityTxContext } from "components/RemoveLiquidity/RemoveLiquidityTxContext";
import { DetailLineItem } from "components/swap/DetailLineItem";
import { useCurrencyInfo } from "hooks/Tokens";
import { useAccount } from "hooks/useAccount";
import { usePositionQueryRefresher } from "hooks/usePositionQueryRefresher";
import useSelectChain from "hooks/useSelectChain";
import { getCurrencyWithOptionalUnwrap } from "pages/Pool/Positions/create/utils";
import { useMemo, useState } from "react";
import { Trans, useTranslation } from "react-i18next";
import { useDispatch } from "react-redux";
import { liquiditySaga } from "state/sagas/liquidity/liquiditySaga";
import { Button, Flex, Separator, Text } from "ui/src";
import { ProgressIndicator } from "uniswap/src/components/ConfirmSwapModal/ProgressIndicator";
import { CurrencyLogo } from "uniswap/src/components/CurrencyLogo/CurrencyLogo";
import { useAccountMeta } from "uniswap/src/contexts/UniswapContext";
import { AccountType } from "uniswap/src/features/accounts/types";
import { useLocalizationContext } from "uniswap/src/features/language/LocalizationContext";
import { useUSDCValue } from "uniswap/src/features/transactions/hooks/useUSDCPrice";
import { isValidLiquidityTxContext } from "uniswap/src/features/transactions/liquidity/types";
import { getSymbolDisplayText } from "uniswap/src/utils/currency";
import { NumberType } from "utilities/src/format/types";
import { useTrace } from "utilities/src/telemetry/trace/TraceContext";
import { serializeLiquidityTxContext } from "../../utils/currencyAmountSerialization";
export function RemoveLiquidityReview({ onClose }) {
  const { t } = useTranslation();
  const { percent, positionInfo, unwrapNativeCurrency, currentTransactionStep, setCurrentTransactionStep } = useRemoveLiquidityModalContext();
  const [steps, setSteps] = useState([]);
  const removeLiquidityTxContext = useRemoveLiquidityTxContext();
  const { formatCurrencyAmount, formatPercent } = useLocalizationContext();
  const walletAvailableCurrency0Amount = useMemo(() => {
    if (positionInfo?.version === ProtocolVersion.V2 && positionInfo.unstakedAmount && positionInfo.liquidityAmount?.quotient) {
      try {
        const totalLp = positionInfo.liquidityAmount.quotient;
        if (totalLp.toString() !== "0") {
          return positionInfo.currency0Amount.multiply(positionInfo.unstakedAmount).divide(totalLp);
        }
      } catch (error) {
        console.error("Error calculating wallet available currency0:", error);
      }
    }
    return positionInfo?.currency0Amount;
  }, [positionInfo]);
  const walletAvailableCurrency1Amount = useMemo(() => {
    if (positionInfo?.version === ProtocolVersion.V2 && positionInfo.unstakedAmount && positionInfo.liquidityAmount?.quotient) {
      try {
        const totalLp = positionInfo.liquidityAmount.quotient;
        if (totalLp.toString() !== "0") {
          return positionInfo.currency1Amount.multiply(positionInfo.unstakedAmount).divide(totalLp);
        }
      } catch (error) {
        console.error("Error calculating wallet available currency1:", error);
      }
    }
    return positionInfo?.currency1Amount;
  }, [positionInfo]);
  const currency0FiatAmount = useUSDCValue(walletAvailableCurrency0Amount) ?? void 0;
  const currency1FiatAmount = useUSDCValue(walletAvailableCurrency1Amount) ?? void 0;
  const selectChain = useSelectChain();
  const startChainId = useAccount().chainId;
  const account = useAccountMeta();
  const dispatch = useDispatch();
  const trace = useTrace();
  const refreshPositions = usePositionQueryRefresher();
  const { txContext, gasFeeEstimateUSD, supportsEip5792 } = removeLiquidityTxContext;
  const onSuccess = () => {
    setSteps([]);
    setCurrentTransactionStep(void 0);
    refreshPositions().catch((error) => {
      console.error("Failed to refresh positions after removing liquidity:", error);
    });
    onClose();
  };
  const onFailure = () => {
    setCurrentTransactionStep(void 0);
  };
  if (!positionInfo) {
    throw new Error("RemoveLiquidityModal must have an initial state when opening");
  }
  const { feeValue0, feeValue1, fiatFeeValue0, fiatFeeValue1 } = usePositionDerivedInfo(positionInfo);
  const { currency0Amount, currency1Amount, chainId, feeTier, version, poolId } = positionInfo;
  const currentPrice = usePositionCurrentPrice(positionInfo);
  const currency0 = getCurrencyWithOptionalUnwrap({
    currency: positionInfo?.currency0Amount.currency,
    shouldUnwrap: unwrapNativeCurrency
  });
  const currency1 = getCurrencyWithOptionalUnwrap({
    currency: positionInfo?.currency1Amount.currency,
    shouldUnwrap: unwrapNativeCurrency
  });
  const {
    unwrappedCurrency0AmountToRemove,
    unwrappedCurrency1AmountToRemove,
    currency0AmountToRemove,
    currency1AmountToRemove
  } = useMemo(() => {
    const txCurrency0 = removeLiquidityTxContext.txContext?.action.currency0Amount;
    const txCurrency1 = removeLiquidityTxContext.txContext?.action.currency1Amount;
    let walletCurrency0Amount2 = currency0Amount;
    let walletCurrency1Amount2 = currency1Amount;
    if (positionInfo?.version === ProtocolVersion.V2 && positionInfo.unstakedAmount && positionInfo.liquidityAmount?.quotient) {
      try {
        const totalLp = positionInfo.liquidityAmount.quotient;
        if (totalLp.toString() !== "0") {
          walletCurrency0Amount2 = currency0Amount.multiply(positionInfo.unstakedAmount).divide(totalLp);
          walletCurrency1Amount2 = currency1Amount.multiply(positionInfo.unstakedAmount).divide(totalLp);
        }
      } catch (error) {
        console.error("Error calculating wallet currency amounts in review:", error);
      }
    }
    const percentNum = Number(percent) || 0;
    const baseRemovalAmount0 = walletCurrency0Amount2.multiply(percentNum).divide(100);
    const baseRemovalAmount1 = walletCurrency1Amount2.multiply(percentNum).divide(100);
    const needsUnwrap0 = !currency0.equals(walletCurrency0Amount2.currency) && currency0.decimals === walletCurrency0Amount2.currency.decimals;
    const needsUnwrap1 = !currency1.equals(walletCurrency1Amount2.currency) && currency1.decimals === walletCurrency1Amount2.currency.decimals;
    const unwrappedCurrency0AmountToRemove2 = txCurrency0 ?? (needsUnwrap0 ? CurrencyAmount.fromRawAmount(currency0, baseRemovalAmount0.quotient) : baseRemovalAmount0);
    const unwrappedCurrency1AmountToRemove2 = txCurrency1 ?? (needsUnwrap1 ? CurrencyAmount.fromRawAmount(currency1, baseRemovalAmount1.quotient) : baseRemovalAmount1);
    const currency0AmountToRemove2 = txCurrency0 ? CurrencyAmount.fromRawAmount(currency0Amount.currency, txCurrency0.quotient) : baseRemovalAmount0;
    const currency1AmountToRemove2 = txCurrency1 ? CurrencyAmount.fromRawAmount(currency1Amount.currency, txCurrency1.quotient) : baseRemovalAmount1;
    console.log("[RemoveLiquidityReview] Amount calculations:", {
      walletCurrency0: { symbol: walletCurrency0Amount2.currency.symbol, decimals: walletCurrency0Amount2.currency.decimals, amount: walletCurrency0Amount2.toExact() },
      walletCurrency1: { symbol: walletCurrency1Amount2.currency.symbol, decimals: walletCurrency1Amount2.currency.decimals, amount: walletCurrency1Amount2.toExact() },
      baseRemoval0: { symbol: baseRemovalAmount0.currency.symbol, decimals: baseRemovalAmount0.currency.decimals, amount: baseRemovalAmount0.toExact() },
      baseRemoval1: { symbol: baseRemovalAmount1.currency.symbol, decimals: baseRemovalAmount1.currency.decimals, amount: baseRemovalAmount1.toExact() },
      unwrapped0: { symbol: unwrappedCurrency0AmountToRemove2.currency.symbol, decimals: unwrappedCurrency0AmountToRemove2.currency.decimals, amount: unwrappedCurrency0AmountToRemove2.toExact() },
      unwrapped1: { symbol: unwrappedCurrency1AmountToRemove2.currency.symbol, decimals: unwrappedCurrency1AmountToRemove2.currency.decimals, amount: unwrappedCurrency1AmountToRemove2.toExact() },
      fromTxContext: { hasTx0: !!txCurrency0, hasTx1: !!txCurrency1 },
      percent: percentNum
    });
    return {
      unwrappedCurrency0AmountToRemove: unwrappedCurrency0AmountToRemove2,
      unwrappedCurrency1AmountToRemove: unwrappedCurrency1AmountToRemove2,
      currency0AmountToRemove: currency0AmountToRemove2,
      currency1AmountToRemove: currency1AmountToRemove2
    };
  }, [removeLiquidityTxContext.txContext?.action.currency0Amount, removeLiquidityTxContext.txContext?.action.currency1Amount, currency0Amount, currency0, currency1Amount, currency1, percent, positionInfo]);
  const currency0AmountToRemoveUSD = useUSDCValue(unwrappedCurrency0AmountToRemove);
  const currency1AmountToRemoveUSD = useUSDCValue(unwrappedCurrency1AmountToRemove);
  const walletCurrency0Amount = useMemo(() => {
    if (positionInfo?.version === ProtocolVersion.V2 && positionInfo.unstakedAmount && positionInfo.liquidityAmount?.quotient) {
      try {
        const totalLp = positionInfo.liquidityAmount.quotient;
        if (totalLp.toString() === "0") {
          return currency0Amount;
        }
        return currency0Amount.multiply(positionInfo.unstakedAmount).divide(totalLp);
      } catch (error) {
        console.error("Error calculating wallet currency0 amount for new position:", error);
        return currency0Amount;
      }
    }
    return currency0Amount;
  }, [positionInfo, currency0Amount]);
  const walletCurrency1Amount = useMemo(() => {
    if (positionInfo?.version === ProtocolVersion.V2 && positionInfo.unstakedAmount && positionInfo.liquidityAmount?.quotient) {
      try {
        const totalLp = positionInfo.liquidityAmount.quotient;
        if (totalLp.toString() === "0") {
          return currency1Amount;
        }
        return currency1Amount.multiply(positionInfo.unstakedAmount).divide(totalLp);
      } catch (error) {
        console.error("Error calculating wallet currency1 amount for new position:", error);
        return currency1Amount;
      }
    }
    return currency1Amount;
  }, [positionInfo, currency1Amount]);
  const newCurrency0Amount = useMemo(() => {
    try {
      const removalAmount = positionInfo?.version === ProtocolVersion.V2 && positionInfo.unstakedAmount && positionInfo.liquidityAmount?.quotient ? walletCurrency0Amount.multiply(Number(percent) || 0).divide(100) : currency0AmountToRemove;
      return walletCurrency0Amount.subtract(removalAmount);
    } catch (error) {
      console.error("Error calculating new currency0 amount:", error);
      return walletCurrency0Amount;
    }
  }, [walletCurrency0Amount, currency0AmountToRemove, positionInfo, percent]);
  const newCurrency1Amount = useMemo(() => {
    try {
      const removalAmount = positionInfo?.version === ProtocolVersion.V2 && positionInfo.unstakedAmount && positionInfo.liquidityAmount?.quotient ? walletCurrency1Amount.multiply(Number(percent) || 0).divide(100) : currency1AmountToRemove;
      return walletCurrency1Amount.subtract(removalAmount);
    } catch (error) {
      console.error("Error calculating new currency1 amount:", error);
      return walletCurrency1Amount;
    }
  }, [walletCurrency1Amount, currency1AmountToRemove, positionInfo, percent]);
  const newCurrency0AmountUSD = useUSDCValue(newCurrency0Amount);
  const newCurrency1AmountUSD = useUSDCValue(newCurrency1Amount);
  const poolTokenPercentage = useGetPoolTokenPercentage(positionInfo);
  const currency0CurrencyInfo = useCurrencyInfo(currency0Amount.currency);
  const currency1CurrencyInfo = useCurrencyInfo(currency1Amount.currency);
  const onDecreaseLiquidity = () => {
    const isValidTx = isValidLiquidityTxContext(txContext);
    if (!account || account?.type !== AccountType.SignerMnemonic || !isValidTx || !positionInfo) {
      return;
    }
    dispatch(
      liquiditySaga.actions.trigger({
        selectChain,
        startChainId,
        account,
        liquidityTxContext: serializeLiquidityTxContext(txContext),
        setCurrentStep: setCurrentTransactionStep,
        setSteps,
        onSuccess,
        onFailure,
        supportsEip5792,
        analytics: {
          ...getLPBaseAnalyticsProperties({
            trace,
            fee: feeTier,
            poolId,
            currency0,
            currency1,
            currency0AmountUsd: currency0AmountToRemoveUSD,
            currency1AmountUsd: currency1AmountToRemoveUSD,
            version
          }),
          expectedAmountBaseRaw: unwrappedCurrency0AmountToRemove?.quotient.toString() ?? "-",
          expectedAmountQuoteRaw: unwrappedCurrency1AmountToRemove?.quotient.toString() ?? "-",
          closePosition: percent === "100"
        }
      })
    );
  };
  return <Flex gap="$gap16">
      <Flex gap="$gap16" px="$padding16">
        <TokenInfo
    currencyAmount={unwrappedCurrency0AmountToRemove}
    currencyUSDAmount={currency0FiatAmount?.multiply(percent).divide(100)}
  />
        <Text variant="body3" color="$neutral2">
          {t("common.and")}
        </Text>
        <TokenInfo
    currencyAmount={unwrappedCurrency1AmountToRemove}
    currencyUSDAmount={currency1FiatAmount?.multiply(percent).divide(100)}
  />
        {positionInfo.version !== ProtocolVersion.V2 && <Flex p="$spacing16" gap="$gap12" background="$surface2" borderRadius="$rounded12">
            <Text variant="body4" color="$neutral2">
              {t("fee.uncollected")}
            </Text>

            <Flex row alignItems="center" justifyContent="space-between">
              <Flex row gap="$gap8" alignItems="center">
                <CurrencyLogo currencyInfo={currency0CurrencyInfo} size={24} />
                <Text variant="body3">{currency0Amount.currency.symbol} fees</Text>
              </Flex>
              <Flex row alignItems="center" gap="$spacing4">
                <Text variant="body3">
                  {formatCurrencyAmount({ value: feeValue0 })} ({formatCurrencyAmount({ value: fiatFeeValue0, type: NumberType.FiatTokenPrice })})
                </Text>
              </Flex>
            </Flex>

            <Flex row alignItems="center" justifyContent="space-between">
              <Flex row gap="$gap8" alignItems="center">
                <CurrencyLogo currencyInfo={currency1CurrencyInfo} size={24} />
                <Text variant="body3">{currency1Amount.currency.symbol} fees</Text>
              </Flex>
              <Flex row alignItems="center" gap="$spacing4">
                <Text variant="body3">
                  {formatCurrencyAmount({ value: feeValue1 })} ({formatCurrencyAmount({ value: fiatFeeValue1, type: NumberType.FiatTokenPrice })})
                </Text>
              </Flex>
            </Flex>
          </Flex>}
      </Flex>
      {currentTransactionStep ? <ProgressIndicator steps={steps} currentStep={currentTransactionStep} /> : <>
          <Separator mx="$padding16" />
          <Flex gap="$gap8" px="$padding16">
            <DetailLineItem
    LineItem={{
      Label: () => <Text variant="body3" color="$neutral2">
                    {t("common.rate")}
                  </Text>,
      Value: () => <Text variant="body3">{`1 ${currentPrice?.baseCurrency.symbol} = ${currentPrice?.toFixed()} ${currentPrice?.quoteCurrency.symbol}`}</Text>
    }}
  />
            <DetailLineItem
    LineItem={{
      Label: () => <Text variant="body3" color="$neutral2">
                    <Trans i18nKey="pool.newSpecificPosition" values={{ symbol: currency0Amount.currency.symbol }} />
                  </Text>,
      Value: () => <Flex row gap="$gap4">
                    <Text variant="body3">
                      {formatCurrencyAmount({ value: newCurrency0Amount, type: NumberType.TokenNonTx })}{" "}
                      {getSymbolDisplayText(newCurrency0Amount?.currency.symbol)}
                    </Text>
                    <Text variant="body3" color="$neutral2">
                      {`(${formatCurrencyAmount({ value: newCurrency0AmountUSD, type: NumberType.FiatStandard })})`}
                    </Text>
                  </Flex>
    }}
  />
            <DetailLineItem
    LineItem={{
      Label: () => <Text variant="body3" color="$neutral2">
                    <Trans i18nKey="pool.newSpecificPosition" values={{ symbol: currency1Amount.currency.symbol }} />
                  </Text>,
      Value: () => <Flex row gap="$gap4">
                    <Text variant="body3">
                      {formatCurrencyAmount({ value: newCurrency1Amount, type: NumberType.TokenNonTx })}{" "}
                      {getSymbolDisplayText(newCurrency1Amount?.currency.symbol)}
                    </Text>
                    <Text variant="body3" color="$neutral2">
                      {`(${formatCurrencyAmount({ value: newCurrency1AmountUSD, type: NumberType.FiatStandard })})`}
                    </Text>
                  </Flex>
    }}
  />
            {poolTokenPercentage ? <DetailLineItem
    LineItem={{
      Label: () => <Text variant="body3" color="$neutral2">
                      {t("addLiquidity.shareOfPool")}
                    </Text>,
      Value: () => <Text variant="body3">{formatPercent(poolTokenPercentage.toFixed())}</Text>
    }}
  /> : null}
          </Flex>
          <Flex row>
            <Button size="large" onPress={onDecreaseLiquidity}>
              {t("common.confirm")}
            </Button>
          </Flex>
        </>}
    </Flex>;
}
