import { UseQueryResult, useQuery } from '@tanstack/react-query'
import { useAccountMeta } from 'uniswap/src/contexts/UniswapContext'
import { useMemo } from 'react'
import { UseQueryApiHelperHookArgs } from 'uniswap/src/data/apiClients/types'
import { CheckApprovalLPRequest, CheckApprovalLPResponse, DecreaseLPPositionRequest, DecreaseLPPositionResponse } from 'uniswap/src/data/tradingApi/__generated__'
import { getAbstractContracts } from 'uniswap/src/constants/abstractContracts'
import { UniverseChainId } from 'uniswap/src/features/chains/types'
import { ReactQueryCacheKey } from 'utilities/src/reactQuery/cache'
import { useReadContracts } from 'wagmi'
import { Address } from 'viem'
import { ethers } from 'ethers'

// ERC20 ABI for allowance function
const ERC20_ABI = [
  {
    name: 'allowance',
    type: 'function',
    stateMutability: 'view',
    inputs: [
      { name: 'owner', type: 'address' },
      { name: 'spender', type: 'address' }
    ],
    outputs: [{ name: '', type: 'uint256' }]
  },
  {
    name: 'approve',
    type: 'function',
    stateMutability: 'nonpayable',
    inputs: [
      { name: 'spender', type: 'address' },
      { name: 'amount', type: 'uint256' }
    ],
    outputs: [{ name: '', type: 'bool' }]
  }
] as const

export function useAbstractRemoveLiquidityApprovalQuery({
  params,
  ...rest
}: UseQueryApiHelperHookArgs<CheckApprovalLPRequest, CheckApprovalLPResponse> & {
  headers?: Record<string, string>
}): UseQueryResult<CheckApprovalLPResponse> {
  const account = useAccountMeta()
  const address = account?.address
  
  // Extract Abstract-specific params from the request
  const abstractParams = useMemo(() => {
    if (!params) return null
    
    try {
      const chainId = params.chainId as UniverseChainId
      const positionToken = params.positionToken
      const positionAmount = params.positionAmount
      
      return {
        chainId,
        positionToken,
        positionAmount,
      }
    } catch (error) {
      console.warn('Failed to extract params from LP approval request:', error)
      return null
    }
  }, [params])

  const contracts = getAbstractContracts(abstractParams?.chainId || UniverseChainId.Mainnet)
  const routerAddress = contracts?.router

  // Build allowance check contract call
  const allowanceContract = useMemo(() => {
    if (!abstractParams || !address || !routerAddress) return null

    return {
      address: abstractParams.positionToken as Address,
      abi: ERC20_ABI,
      functionName: 'allowance',
      args: [address as Address, routerAddress as Address]
    }
  }, [abstractParams, address, routerAddress])

  // Single allowance check via multicall
  const { data: allowanceResult, isLoading, isError, error, refetch } = useReadContracts({
    contracts: allowanceContract ? [allowanceContract] : [],
    query: {
      enabled: Boolean(abstractParams && address && routerAddress && allowanceContract),
      refetchInterval: 10000, // Refetch every 10 seconds
    }
  })

  const queryKey = [ReactQueryCacheKey.AbstractRemoveLiquidityApproval, abstractParams, address]

  return useQuery<CheckApprovalLPResponse>({
    queryKey: [...queryKey, allowanceResult?.[0]?.result?.toString()],
    enabled: Boolean(abstractParams && address && allowanceResult && !isLoading),
    queryFn: async () => {
      if (!abstractParams || !address || !allowanceResult || !routerAddress) {
        throw new Error('Invalid parameters for Abstract remove liquidity approval')
      }

      const response: CheckApprovalLPResponse = {
        positionTokenApproval: null,
        gasFeePositionTokenApproval: null,
      }

      // Parse allowance result
      const allowanceData = allowanceResult[0]
      const currentAllowance = allowanceData?.status === 'success' ? 
        BigInt(allowanceData.result?.toString() || '0') : 0n
      
      const amountNeeded = BigInt(abstractParams.positionAmount)

      // Check if approval is needed
      if (currentAllowance < amountNeeded) {
        response.positionTokenApproval = {
          to: abstractParams.positionToken,
          data: new ethers.utils.Interface(ERC20_ABI).encodeFunctionData('approve', [
            routerAddress,
            amountNeeded.toString()
          ]),
          value: '0',
          from: address,
          chainId: abstractParams.chainId,
        }
        response.gasFeePositionTokenApproval = '50000000000000' // 50k gas * 1 gwei
      }

      return response
    },
    ...rest,
  })
}

export function useAbstractRemoveLiquidityCalldataQuery({
  params,
  deadlineInMinutes,
  ...rest
}: UseQueryApiHelperHookArgs<DecreaseLPPositionRequest, DecreaseLPPositionResponse> & {
  headers?: Record<string, string>
  deadlineInMinutes?: number
}): UseQueryResult<DecreaseLPPositionResponse> {
  const account = useAccountMeta()
  const address = account?.address

  // Extract and validate parameters
  const abstractParams = useMemo(() => {
    if (!params || !address) return null

    try {
      const isV2 = params.protocol === 'V2' || (params.liquidity0 && params.liquidity1)
      const isV3 = params.protocol === 'V3' || params.tokenId

      if (!isV2 && !isV3) {
        throw new Error('Unsupported protocol version')
      }

      return {
        ...params,
        isV2,
        isV3,
        walletAddress: address,
      }
    } catch (error) {
      console.warn('Failed to extract params from decrease LP request:', error)
      return null
    }
  }, [params, address])

  const contracts = getAbstractContracts(abstractParams?.chainId as UniverseChainId || UniverseChainId.Mainnet)
  const routerAddress = contracts?.router
  const nftManagerAddress = contracts?.nonfungiblePositionManager

  // Build multicall contracts for any chain calls we might need
  const multicallContracts = useMemo(() => {
    if (!abstractParams) return []

    const contractCalls = []

    // For V3: We might need to call the NFT manager to get position details
    // For now, we'll assume we have all the data we need from params
    // If we need more data, we can add multicall here

    return contractCalls
  }, [abstractParams])

  // Single multicall (if needed)
  const { data: multicallResults, isLoading: multicallLoading } = useReadContracts({
    contracts: multicallContracts,
    query: {
      enabled: Boolean(abstractParams && multicallContracts.length > 0),
    }
  })

  const queryKey = [ReactQueryCacheKey.AbstractRemoveLiquidityCalldata, abstractParams]

  return useQuery<DecreaseLPPositionResponse>({
    queryKey,
    enabled: Boolean(abstractParams && !multicallLoading),
    queryFn: async () => {
      if (!abstractParams) {
        throw new Error('Invalid parameters for Abstract remove liquidity calldata')
      }

      const deadline = Math.floor(Date.now() / 1000) + (deadlineInMinutes ? deadlineInMinutes * 60 : 1200)

      if (abstractParams.isV2) {
        // V2 Remove Liquidity
        if (!routerAddress) {
          throw new Error('V2 Router address not found for this chain')
        }

        // Calculate minimum amounts with slippage tolerance
        // Handle slippage tolerance - can be passed as percentage (4) or decimal (0.04)
        let normalizedSlippage = abstractParams.slippageTolerance
        if (normalizedSlippage && normalizedSlippage > 1) {
          // If greater than 1, assume it's a percentage and convert to decimal
          normalizedSlippage = normalizedSlippage / 100
          // Converted from percentage to decimal
        }
        
        // Validate slippage tolerance
        if (normalizedSlippage && (normalizedSlippage > 0.5 || normalizedSlippage < 0)) {
          // Invalid slippage tolerance
          throw new Error(`Invalid slippage tolerance: ${abstractParams.slippageTolerance}. Must be between 0% and 50%`)
        }
        
        const slippageBps = normalizedSlippage ? Math.floor(normalizedSlippage * 10000) : 50
        const slippageMultiplier = 10000 - slippageBps
        
        // Additional validation
        if (slippageMultiplier < 0 || slippageMultiplier > 10000) {
          // Invalid slippage multiplier
          throw new Error(`Invalid slippage calculation resulted in multiplier: ${slippageMultiplier}`)
        }
        
        const liquidity0 = abstractParams.liquidity0 || '0'
        const liquidity1 = abstractParams.liquidity1 || '0'
        
        // Calculate the percentage-based amounts for slippage protection
        const percentageMultiplier = BigInt(Math.floor((abstractParams.liquidityPercentageToDecrease || 0) * 100))
        const expectedAmount0 = (BigInt(liquidity0) * percentageMultiplier) / 10000n
        const expectedAmount1 = (BigInt(liquidity1) * percentageMultiplier) / 10000n
        
        const amountAMin = (expectedAmount0 * BigInt(slippageMultiplier)) / 10000n
        const amountBMin = (expectedAmount1 * BigInt(slippageMultiplier)) / 10000n

        // The positionLiquidity is already the percentage-based amount calculated in hooks.ts
        // So we use it directly without applying percentage again
        const liquidityToRemove = BigInt(abstractParams.positionLiquidity || '0')

        const token0 = abstractParams.position?.pool?.token0 || '0x0'
        const token1 = abstractParams.position?.pool?.token1 || '0x0'
        
        // Check if either token is ZERO_ADDRESS (indicating ETH withdrawal)
        const isToken0ETH = token0 === '0x0' || token0 === '0x0000000000000000000000000000000000000000'
        const isToken1ETH = token1 === '0x0' || token1 === '0x0000000000000000000000000000000000000000'
        
        let data: string
        // Stable flag passed from UI (for V2 pools)
        const stableFlag = Boolean((abstractParams.position?.pool as any)?.stable)
        
        if (isToken0ETH || isToken1ETH) {
          // Use removeLiquidityETH for ETH withdrawal
          const routerETHABI = [
            {
              name: 'removeLiquidityETH',
              type: 'function',
              stateMutability: 'nonpayable',
              inputs: [
                { name: 'token', type: 'address' },
                { name: 'stable', type: 'bool' },
                { name: 'liquidity', type: 'uint256' },
                { name: 'amountTokenMin', type: 'uint256' },
                { name: 'amountETHMin', type: 'uint256' },
                { name: 'to', type: 'address' },
                { name: 'deadline', type: 'uint256' }
              ],
              outputs: [
                { name: 'amountToken', type: 'uint256' },
                { name: 'amountETH', type: 'uint256' }
              ]
            }
          ]
          
          // Determine which token is the non-ETH token
          const nonETHToken = isToken0ETH ? token1 : token0
          const amountTokenMin = isToken0ETH ? amountBMin : amountAMin
          const amountETHMin = isToken0ETH ? amountAMin : amountBMin
          
          data = new ethers.utils.Interface(routerETHABI).encodeFunctionData('removeLiquidityETH', [
            nonETHToken,
            stableFlag, // pass actual stable/volatile flag
            liquidityToRemove.toString(),
            amountTokenMin.toString(),
            amountETHMin.toString(),
            address,
            deadline
          ])
        } else {
          // Use regular removeLiquidity for token/token pairs
          const routerABI = [
            {
              name: 'removeLiquidity',
              type: 'function',
              stateMutability: 'nonpayable',
              inputs: [
                { name: 'tokenA', type: 'address' },
                { name: 'tokenB', type: 'address' },
                { name: 'stable', type: 'bool' },
                { name: 'liquidity', type: 'uint256' },
                { name: 'amountAMin', type: 'uint256' },
                { name: 'amountBMin', type: 'uint256' },
                { name: 'to', type: 'address' },
                { name: 'deadline', type: 'uint256' }
              ],
              outputs: [
                { name: 'amountA', type: 'uint256' },
                { name: 'amountB', type: 'uint256' }
              ]
            }
          ]

          data = new ethers.utils.Interface(routerABI).encodeFunctionData('removeLiquidity', [
            token0,
            token1,
            stableFlag, // pass actual stable/volatile flag
            liquidityToRemove.toString(),
            amountAMin.toString(),
            amountBMin.toString(),
            address,
            deadline
          ])
        }

        return {
          decrease: {
            to: routerAddress,
            data,
            value: '0',
            from: address,
            chainId: abstractParams.chainId,
          },
          gasFee: '150000000000000' // 150k gas * 1 gwei for V2
        }
      } else if (abstractParams.isV3) {
        // V3 Remove Liquidity
        if (!nftManagerAddress) {
          throw new Error('V3 NFT Manager address not found for this chain')
        }

        const nftManagerABI = [
          {
            name: 'decreaseLiquidity',
            type: 'function',
            stateMutability: 'nonpayable',
            inputs: [
              {
                name: 'params',
                type: 'tuple',
                components: [
                  { name: 'tokenId', type: 'uint256' },
                  { name: 'liquidity', type: 'uint128' },
                  { name: 'amount0Min', type: 'uint256' },
                  { name: 'amount1Min', type: 'uint256' },
                  { name: 'deadline', type: 'uint256' }
                ]
              }
            ],
            outputs: [
              { name: 'amount0', type: 'uint256' },
              { name: 'amount1', type: 'uint256' }
            ]
          },
          {
            name: 'collect',
            type: 'function',
            stateMutability: 'payable',
            inputs: [
              {
                name: 'params',
                type: 'tuple',
                components: [
                  { name: 'tokenId', type: 'uint256' },
                  { name: 'recipient', type: 'address' },
                  { name: 'amount0Max', type: 'uint128' },
                  { name: 'amount1Max', type: 'uint128' }
                ]
              }
            ],
            outputs: [
              { name: 'amount0', type: 'uint256' },
              { name: 'amount1', type: 'uint256' }
            ]
          },
          {
            name: 'multicall',
            type: 'function',
            stateMutability: 'payable',
            inputs: [
              { name: 'data', type: 'bytes[]' }
            ],
            outputs: [
              { name: 'results', type: 'bytes[]' }
            ]
          }
        ]

        // Calculate minimum amounts with slippage tolerance
        // Handle slippage tolerance - can be passed as percentage (4) or decimal (0.04)
        let normalizedSlippage = abstractParams.slippageTolerance
        if (normalizedSlippage && normalizedSlippage > 1) {
          // If greater than 1, assume it's a percentage and convert to decimal
          normalizedSlippage = normalizedSlippage / 100
          // Converted from percentage to decimal
        }
        
        // Validate slippage tolerance
        if (normalizedSlippage && (normalizedSlippage > 0.5 || normalizedSlippage < 0)) {
          // Invalid slippage tolerance
          throw new Error(`Invalid slippage tolerance: ${abstractParams.slippageTolerance}. Must be between 0% and 50%`)
        }
        
        const slippageBps = normalizedSlippage ? Math.floor(normalizedSlippage * 10000) : 50
        const slippageMultiplier = 10000 - slippageBps
        
        // Additional validation
        if (slippageMultiplier < 0 || slippageMultiplier > 10000) {
          // Invalid slippage multiplier
          throw new Error(`Invalid slippage calculation resulted in multiplier: ${slippageMultiplier}`)
        }
        
        const expectedAmount0 = abstractParams.expectedTokenOwed0RawAmount || '0'
        const expectedAmount1 = abstractParams.expectedTokenOwed1RawAmount || '0'
        
        const amount0Min = (BigInt(expectedAmount0) * BigInt(slippageMultiplier)) / 10000n
        const amount1Min = (BigInt(expectedAmount1) * BigInt(slippageMultiplier)) / 10000n

        // The positionLiquidity is already the percentage-based amount calculated in hooks.ts
        // So we use it directly without applying percentage again
        const liquidityToRemove = BigInt(abstractParams.positionLiquidity || '0')


        const tokenId = abstractParams.tokenId || 0
        
        const decreaseParams = {
          tokenId,
          liquidity: liquidityToRemove.toString(),
          amount0Min: amount0Min.toString(),
          amount1Min: amount1Min.toString(),
          deadline
        }

        // Collect params - use max uint128 to collect all owed tokens
        const collectParams = {
          tokenId,
          recipient: address,
          amount0Max: '340282366920938463463374607431768211455', // max uint128
          amount1Max: '340282366920938463463374607431768211455'  // max uint128
        }

        const iface = new ethers.utils.Interface(nftManagerABI)
        
        // Encode both calls
        const decreaseData = iface.encodeFunctionData('decreaseLiquidity', [decreaseParams])
        const collectData = iface.encodeFunctionData('collect', [collectParams])
        
        // Create multicall to batch both operations
        const multicallData = iface.encodeFunctionData('multicall', [[decreaseData, collectData]])

        return {
          decrease: {
            to: nftManagerAddress,
            data: multicallData,
            value: '0',
            from: address,
            chainId: abstractParams.chainId,
          },
          gasFee: '250000000000000' // 250k gas * 1 gwei for V3 multicall
        }
      }

      throw new Error('Unsupported protocol version for remove liquidity')
    },
    ...rest,
  })
}
